-- Metadata/policy contract only; no blob bytes are uploaded by SQL. All fixtures roll back.
begin;
create function pg_temp.p_id(n integer) returns uuid language sql immutable as $$select ('f7000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.p_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.p_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected SQLSTATE %',state;end$$;
create function pg_temp.p_player(pts integer) returns jsonb language sql as $$select jsonb_build_object('jerseyNumber','00','name','Source player','starter',false,'captain',false,'didNotPlay',false,'secondsPlayed',10,'fieldGoals',jsonb_build_object('made',1,'attempted',1),'twoPoints',jsonb_build_object('made',case when pts=2 then 1 else 0 end,'attempted',case when pts=2 then 1 else 0 end),'threePoints',jsonb_build_object('made',case when pts=3 then 1 else 0 end,'attempted',case when pts=3 then 1 else 0 end),'freeThrows',jsonb_build_object('made',0,'attempted',0),'offensiveRebounds',0,'defensiveRebounds',0,'rebounds',0,'assists',0,'turnovers',0,'steals',0,'blocks',0,'foulsCommitted',0,'foulsReceived',null,'plusMinus',null,'efficiency',pts,'points',pts)$$;
create function pg_temp.p_command(n integer default 10,h text default repeat('a',64)) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.p_id(n),'source',jsonb_build_object('id',pg_temp.p_id(n+1),'disputeId',pg_temp.p_id(3),'filename','Fixture.pdf','sha256',h,'byteSize',10,'pageCount',2,'parsed',jsonb_build_object('format','BASKETBALL_SITE','parserVersion','basketball-site-v1','competitionName',null,'gameNumber',null,'scheduledLocal','2026-05-13T20:30','durationSeconds',null,'venue','Fixture','warnings','[]'::jsonb,'teams',jsonb_build_array(jsonb_build_object('name','Home','abbreviation','H','score',2,'periodScores',null,'players',jsonb_build_array(pg_temp.p_player(2))),jsonb_build_object('name','Away','abbreviation','A','score',3,'periodScores',null,'players',jsonb_build_array(pg_temp.p_player(3)))))))$$;
grant execute on function pg_temp.p_id(integer),pg_temp.p_assert(boolean,text),pg_temp.p_error(text,text),pg_temp.p_player(integer),pg_temp.p_command(integer,text) to anon,authenticated,service_role;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.p_id(98)),(pg_temp.p_id(99));
insert into public.admin_access(user_id) values(pg_temp.p_id(98));
insert into public.championships(id,name) values(pg_temp.p_id(1),'G3 fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.p_id(2),pg_temp.p_id(1),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.p_id(3),pg_temp.p_id(2),'masculino','Adulto');
set local role anon;
select pg_temp.p_error('select public.prepare_pdf_source(pg_temp.p_command())','42501');
set local role authenticated;
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000099';
select pg_temp.p_error('select public.prepare_pdf_source(pg_temp.p_command())','PT403');
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000098';
select pg_temp.p_assert((public.prepare_pdf_source(pg_temp.p_command())->>'id')=pg_temp.p_id(11)::text,'source prepared');
select pg_temp.p_assert(public.prepare_pdf_source(pg_temp.p_command())->'ready'='false','retry same prepared intent');
select pg_temp.p_assert(public.get_pdf_source(pg_temp.p_id(11))->'ready'='false','metadata is not a finished upload');
select pg_temp.p_error($q$select public.finish_pdf_source(jsonb_build_object('commandId',pg_temp.p_id(10),'sourceId',pg_temp.p_id(11)))$q$,'PT409');
select pg_temp.p_error($q$select public.prepare_pdf_source(jsonb_set(pg_temp.p_command(),'{source,filename}','"different.pdf"'))$q$,'PT409');
select pg_temp.p_error($q$select public.prepare_pdf_source(jsonb_set(pg_temp.p_command(20,repeat('b',64)),'{source,parsed,teams,0,score}','99'))$q$,'PT400');
select pg_temp.p_error($q$insert into storage.objects(bucket_id,name,metadata) values('boxscore-sources','outside.pdf','{}')$q$,'42501');
insert into storage.objects(bucket_id,name,metadata,owner_id) values('boxscore-sources','sources/'||pg_temp.p_id(11)::text||'.pdf','{"mimetype":"application/pdf","size":10}',pg_temp.p_id(98)::text);
select pg_temp.p_assert((public.finish_pdf_source(jsonb_build_object('commandId',pg_temp.p_id(10),'sourceId',pg_temp.p_id(11)))->>'version')::int=2,'finish only after object metadata');
select pg_temp.p_assert((public.finish_pdf_source(jsonb_build_object('commandId',pg_temp.p_id(10),'sourceId',pg_temp.p_id(11)))->>'version')::int=2,'finish replay');
select pg_temp.p_assert(public.get_pdf_source(pg_temp.p_id(11))->'ready'='true','ready document');
select pg_temp.p_assert(public.prepare_pdf_source(pg_temp.p_command(30))->'duplicate'='true','same file is explicit duplicate');
select pg_temp.p_assert((public.prepare_pdf_source(pg_temp.p_command(30))->>'id')=pg_temp.p_id(11)::text,'duplicate returns original identity');
update storage.objects set metadata='{}' where bucket_id='boxscore-sources';
select pg_temp.p_error($q$delete from storage.objects where bucket_id='boxscore-sources'$q$,'42501');
select pg_temp.p_assert(exists(select 1 from pg_policy where polrelid='storage.objects'::regclass and polname='bdb_pdf_no_delete' and not polpermissive),'restrictive API deletion guard present');
select pg_temp.p_assert((select count(*) from storage.objects where name='sources/'||pg_temp.p_id(11)::text||'.pdf')=1,'ready original cannot be overwritten or deleted');
select pg_temp.p_error('select * from private.pdf_source_commands','42501');
select pg_temp.p_error('insert into public.pdf_sources(id) values(pg_temp.p_id(77))','42501');
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000099';
select pg_temp.p_assert(public.get_pdf_source(pg_temp.p_id(11)) is null,'nonadmin metadata denied');
select pg_temp.p_assert((select count(*) from storage.objects where bucket_id='boxscore-sources')=0,'nonadmin object denied');
reset role;
update public.admin_access set enabled=false;
set local role authenticated;
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000098';
select pg_temp.p_error('select public.prepare_pdf_source(pg_temp.p_command())','PT403');
select pg_temp.p_error($q$select public.finish_pdf_source(jsonb_build_object('commandId',pg_temp.p_id(10),'sourceId',pg_temp.p_id(11)))$q$,'PT403');
set local role service_role;
select pg_temp.p_error('select public.get_pdf_source(pg_temp.p_id(11))','42501');
reset role;
select pg_temp.p_assert((select not public and file_size_limit=10485760 and allowed_mime_types=array['application/pdf'] from storage.buckets where id='boxscore-sources'),'private bounded bucket');
rollback;
